                'Консультант Afarer по безопасности, бывший советник по охране губернатора Свальбарда Бьёрн Викан, совместно разработал 3-дневную программу обучения для 12 гидов Hurtigruten. «Arctic Paddle Safety Protocol» включал ротацию наблюдения за медведями (один выделенный гид на вахте наблюдения с винтовкой калибра .308 и ракетницей — стандартное требование Свальбарда), построение группы (линия в пределах 50 м, никогда дальше 200 м от зодиака), быструю эвакуацию (посадка всей группы менее чем за 90 секунд, тренировалась еженедельно) и экстренное реагирование на гипотермию. Afarer предоставил водонепроницаемые ламинированные карточки быстрого доступа для каждого гида. Каждая сессия ограничивалась 8 гостями с 2 гидами и 1 вооружённым охранным зодиаком в 100 м. Замеченные во время гребли белые медведи — 2 инцидента в сезоне 2024 года, оба разрешены предупредительными выстрелами ракетниц, без травм. Гости оценили «уверенность в безопасности» на 4,9/5.',
